entries={}; audit=[]
def add(key,author,title,year,journal,volume,pages,url,verification,locator,evidence,doi='',number='',typ='article',extra=None,opened=None,source_ref='',note='verified'):
    fields=dict(author=author,title=title,year=str(year))
    if journal: fields['journal' if typ=='article' else 'publisher']=journal
    if volume:fields['volume']=volume
    if number:fields['number']=number
    if pages:fields['pages']=pages
    if doi:fields['doi']=doi
    fields['url']=url;fields['note']=note
    if extra:fields.update(extra)
    entries[key]='@'+typ+'{'+key+',\n'+',\n'.join('  '+k+' = {'+str(v)+'}' for k,v in fields.items())+'\n}'
    audit.append(dict(key=key,url=url,verification=verification,locator=locator,opened_url=opened or url,opened_url_evidence=evidence,tool_reference=source_ref,accessed='2026-11-10',note=note))

