# Reuse exact cumulative bibliography keys and entries; our audit does not inherit
# a stronger read-result claim merely because an earlier chapter read that work.
def extract(source,key):
    s=source.read_text();m=re.search(r'@\w+\s*\{'+re.escape(key)+r'\s*,',s)
    assert m,key
    i=m.end();depth=1
    while depth:
        if s[i]=='{':depth+=1
        elif s[i]=='}':depth-=1
        i+=1
    return s[m.start():i]
